/* com.portal.board.com.BBSUseInfoManageMapper.selectBBSUseInfs */ SELECT a.BBS_ID, e.BBS_NM, a.TRGET_ID, a.REGIST_SE_CODE, b.CODE_NM AS REGIST_SE_CODE_NM, a.USE_AT, a.FRST_REGISTER_ID, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, '시스템 활용' AS CMMNTY_ID, '시스템 활용' AS CMMNTY_NM, '시스템 활용' AS CLB_ID, '시스템 활용' AS CLB_NM, '시스템 활용' AS BBS_TY_CODE FROM LETTNBBSUSE a LEFT OUTER JOIN LETTNBBSMASTER e ON a.BBS_ID = e.BBS_ID LEFT OUTER JOIN LETTCCMMNDETAILCODE b ON b.CODE = a.REGIST_SE_CODE AND b.CODE_ID = 'COM001' WHERE a.REGIST_SE_CODE != 'REGC07'
AND e.BBS_NM LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

