mapper.select:
/* com.portal.board.com.BBSUseInfoManageMapper.selectBBSUseInfsByTrget */ SELECT * FROM ( /* 1) 개별 사용자 권한 지정 건 */ SELECT a.BBS_ID, b.BBS_NM, a.TRGET_ID, d.USER_NM, a.REGIST_SE_CODE, c.CODE_NM AS REGIST_SE_CODE_NM, a.USE_AT, a.FRST_REGISTER_ID, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM FROM LETTNBBSUSE a LEFT OUTER JOIN LETTNBBSMASTER b ON a.BBS_ID = b.BBS_ID LEFT OUTER JOIN LETTCCMMNDETAILCODE c ON c.CODE = a.REGIST_SE_CODE LEFT OUTER JOIN COMVNUSERMASTER d ON a.TRGET_ID = d.ESNTL_ID WHERE a.BBS_ID IN ( SELECT BBS_ID FROM LETTNBBSUSE WHERE TRGET_ID = #{trgetId} AND USE_AT = 'Y' ) AND a.REGIST_SE_CODE = 'REGC07'
UNION ALL
/* 2) 전체 사용자 대상 권한 지정 건 */ SELECT a.BBS_ID, b.BBS_NM, a.TRGET_ID, '[전체]' AS USER_NM, a.REGIST_SE_CODE, c.CODE_NM AS REGIST_SE_CODE_NM, a.USE_AT, a.FRST_REGISTER_ID, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM FROM LETTNBBSUSE a LEFT OUTER JOIN LETTNBBSMASTER b ON a.BBS_ID = b.BBS_ID LEFT OUTER JOIN LETTCCMMNDETAILCODE c ON c.CODE = a.REGIST_SE_CODE WHERE a.BBS_ID IN ( SELECT BBS_ID FROM LETTNBBSUSE WHERE TRGET_ID = #{trgetId} ) AND a.REGIST_SE_CODE IN ('REGC05', 'REGC06')
UNION ALL
/* 3) 커뮤니티/동호회 회원 중 아직 미등록된 사용자 건 */ SELECT a.BBS_ID, b.BBS_NM, CASE WHEN e.EMPLYR_ID IS NULL THEN f.EMPLYR_ID ELSE e.EMPLYR_ID END AS TRGET_ID, CASE WHEN g.USER_NM IS NULL THEN h.USER_NM ELSE g.USER_NM END AS USER_NM, 'REGC07' AS REGIST_SE_CODE, '게시판사용자등록' AS REGIST_SE_CODE_NM, '' AS USE_AT, '' AS FRST_REGISTER_ID, '' AS FRST_REGIST_PNTTM FROM LETTNBBSUSE a LEFT OUTER JOIN LETTNBBSMASTER b ON a.BBS_ID = b.BBS_ID LEFT OUTER JOIN LETTCCMMNDETAILCODE c ON c.CODE = a.REGIST_SE_CODE LEFT OUTER JOIN LETTNCMMNTYUSER e ON e.CMMNTY_ID = #{trgetId} LEFT OUTER JOIN LETTNCLUBUSER f ON f.CLB_ID = #{trgetId} LEFT OUTER JOIN COMVNUSERMASTER g ON e.EMPLYR_ID = g.ESNTL_ID LEFT OUTER JOIN COMVNUSERMASTER h ON f.EMPLYR_ID = h.ESNTL_ID WHERE a.BBS_ID IN ( SELECT BBS_ID FROM LETTNBBSUSE WHERE TRGET_ID = #{trgetId} AND USE_AT = 'Y' ) AND a.REGIST_SE_CODE IN ('REGC05', 'REGC06') AND ( (a.BBS_ID, e.EMPLYR_ID) NOT IN (SELECT BBS_ID, TRGET_ID FROM LETTNBBSUSE) OR (a.BBS_ID, f.EMPLYR_ID) NOT IN (SELECT BBS_ID, TRGET_ID FROM LETTNBBSUSE) ) ) tt
WHERE tt.USER_NM LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY tt.USER_NM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

